const practical={
es:{home:'Inicio',order:'Cómo encargar',terms:'Condiciones de venta',legal:'Menciones legales',privacy:'Privacidad',draft:'BORRADOR · PENDIENTE DE COMPLETAR Y VALIDAR',notice:'Esta página forma parte de la maqueta. Las condiciones comerciales y los datos legales todavía no están aprobados para la publicación definitiva.',orderTitle:'Tu guitarra empieza con un diálogo.',orderLead:'Elegir un instrumento es un encuentro entre tu manera de tocar y el trabajo del taller.',steps:[['01 · Conversar','Cuéntame qué música tocas, qué esperas del instrumento y qué modelo te interesa. Podemos conversar sobre la posibilidad de probar las guitarras.'],['02 · Definir el instrumento','Revisamos el modelo, las preferencias de sonido y comodidad, las maderas y los detalles que pueden adaptarse al proyecto.'],['03 · Recibir una propuesta','Antes de confirmar, definimos por escrito las características, el precio, los impuestos aplicables, el plazo estimado y las modalidades de pago y entrega.'],['04 · Construcción y entrega','El instrumento se realiza según el proyecto acordado. La recogida o el envío y las indicaciones de cuidado se organizan con el taller.']],contact:'Conversar sobre un encargo',seeTerms:'Consultar las condiciones de venta',termsLead:'Estructura de trabajo para acordar las condiciones propias del taller. No se puede formalizar una compra ni realizar pagos desde esta maqueta.',clauses:[['Vendedor y ámbito','Completar la identidad jurídica del vendedor y definir las condiciones aplicables a instrumentos disponibles, encargos personalizados y ventas a particulares o profesionales.'],['Presupuesto y confirmación','Definir la validez del presupuesto, el procedimiento de aceptación y el momento de confirmación del pedido.'],['Precio y pago','Completar moneda, impuestos, medios de pago, naturaleza y cuantía del pago inicial, vencimientos y saldo. No se ha fijado ningún porcentaje ni importe en esta maqueta.'],['Plazos y modificaciones','Definir cómo se comunica el plazo, cómo se tratan las modificaciones solicitadas y qué ocurre ante un retraso.'],['Entrega y transporte','Precisar recogida o envío, destinos, embalaje, gastos, responsabilidades y procedimiento ante daños de transporte.'],['Cancelación, devolución y desistimiento','Redactar las condiciones según el tipo de venta y de instrumento, incluidos los derechos aplicables y, cuando corresponda, la excepción para bienes fabricados según especificaciones o claramente personalizados. No se establece aquí una exclusión general de devoluciones.'],['Garantías y cuidado','Distinguir las garantías legales aplicables de cualquier garantía comercial adicional. Completar alcance, atención de incidencias e instrucciones de conservación sin reducir los derechos legales.'],['Reclamaciones y mediación','Completar el contacto para reclamaciones y los datos del mediador de consumo competente, además de las vías de resolución de conflictos aplicables.']],legalLead:'Información del editor del sitio y de su alojamiento definitivo.',fields:[['Nombre del taller','Víctor Iermito · Luthier'],['Actividad','Construcción artesanal de guitarras clásicas · Francia'],['Titular y forma jurídica','Por completar y verificar'],['Domicilio profesional','Por completar'],['Identificación y registro (SIREN/SIRET y registro aplicable)','Por completar'],['IVA, si corresponde','Por completar'],['Correo profesional y teléfono','Por confirmar para publicación'],['Responsable de publicación','Por confirmar'],['Alojamiento definitivo: entidad, dirección y teléfono','Por completar cuando se elija el alojamiento final']],rights:'Textos, fotografías y logotipo',rightsText:'Antes de publicar, confirmar la titularidad y las autorizaciones de uso de cada fotografía, texto, grabación y elemento gráfico. Los enlaces externos remiten a sitios con sus propias condiciones.',privacyLead:'Funcionamiento de esta maqueta y puntos que deberá completar la política del sitio definitivo.',privacySections:[['Idioma','La maqueta guarda la preferencia de idioma en el navegador para recordarla en futuras visitas.'],['Cámara y QR','La cámara se solicita al pulsar el botón de escaneo y requiere tu permiso. El código de esta maqueta analiza las imágenes en el dispositivo para leer el QR; no incluye una función para enviarlas al taller. También puedes introducir el número de serie.'],['Contacto y enlaces externos','Los botones de contacto abren Instagram. No hay un formulario de contacto ni un sistema de pago propio en esta maqueta. Al visitar otras plataformas se aplican sus políticas.'],['Política definitiva pendiente','Completar responsable, contacto de privacidad, finalidades, bases jurídicas, destinatarios, conservación, derechos y reclamación ante la CNIL. Revisar también los registros, cookies y servicios del alojamiento final.']]},
fr:{home:'Accueil',order:'Commander une guitare',terms:'Conditions générales de vente',legal:'Mentions légales',privacy:'Confidentialité',draft:'PROJET · À COMPLÉTER ET À VALIDER',notice:'Cette page fait partie de la maquette. Les conditions commerciales et les informations légales ne sont pas encore validées pour la publication définitive.',orderTitle:'Votre guitare commence par un dialogue.',orderLead:'Choisir un instrument, c’est faire se rencontrer votre façon de jouer et le travail de l’atelier.',steps:[['01 · Échanger','Parlez-moi de votre musique, de vos attentes et du modèle qui vous intéresse. Nous pouvons envisager un essai des guitares.'],['02 · Définir l’instrument','Nous précisons le modèle, vos préférences sonores et de confort, les bois et les détails qui peuvent être adaptés au projet.'],['03 · Recevoir une proposition','Avant confirmation, nous définissons par écrit les caractéristiques, le prix, les taxes applicables, le délai estimé et les modalités de paiement et de livraison.'],['04 · Fabrication et remise','L’instrument est réalisé selon le projet convenu. Le retrait ou l’expédition et les conseils d’entretien sont organisés avec l’atelier.']],contact:'Parlons d’une commande',seeTerms:'Consulter les conditions de vente',termsLead:'Trame de travail pour définir les conditions propres à l’atelier. Cette maquette ne permet ni de conclure un achat ni de payer.',clauses:[['Vendeur et champ d’application','Compléter l’identité juridique du vendeur et définir les conditions applicables aux instruments disponibles, aux commandes personnalisées et aux ventes aux particuliers ou professionnels.'],['Devis et confirmation','Définir la durée de validité du devis, son acceptation et le moment de confirmation de la commande.'],['Prix et règlement','Compléter la devise, les taxes, les moyens de paiement, la nature et le montant du versement initial, les échéances et le solde. Aucun pourcentage ni montant n’est fixé dans cette maquette.'],['Délais et modifications','Préciser la communication des délais, le traitement des modifications demandées et les dispositions en cas de retard.'],['Livraison et transport','Préciser retrait ou expédition, destinations, emballage, frais, responsabilités et procédure en cas de dommage pendant le transport.'],['Annulation, retours et rétractation','Rédiger les conditions selon le type de vente et d’instrument, les droits applicables et, le cas échéant, l’exception pour les biens confectionnés selon les spécifications du consommateur ou nettement personnalisés. Aucune exclusion générale des retours n’est établie ici.'],['Garanties et entretien','Distinguer les garanties légales applicables de toute garantie commerciale supplémentaire. Compléter leur portée, le traitement des réclamations et les conseils de conservation sans réduire les droits légaux.'],['Réclamations et médiation','Compléter les coordonnées de réclamation et du médiateur de la consommation compétent ainsi que les voies de règlement des litiges applicables.']],legalLead:'Informations sur l’éditeur du site et son hébergement définitif.',fields:[['Nom de l’atelier','Victor Iermito · Luthier'],['Activité','Fabrication artisanale de guitares classiques · France'],['Exploitant et forme juridique','À compléter et à vérifier'],['Adresse professionnelle','À compléter'],['Identification et immatriculation (SIREN/SIRET et registre applicable)','À compléter'],['TVA, le cas échéant','À compléter'],['Courriel professionnel et téléphone','À confirmer pour publication'],['Responsable de publication','À confirmer'],['Hébergement définitif : entité, adresse et téléphone','À compléter après le choix de l’hébergement final']],rights:'Textes, photographies et logo',rightsText:'Avant publication, confirmer les droits et autorisations d’utilisation de chaque photographie, texte, enregistrement et élément graphique. Les liens externes renvoient vers des sites soumis à leurs propres conditions.',privacyLead:'Fonctionnement de cette maquette et éléments à compléter pour la politique du site définitif.',privacySections:[['Langue','La maquette mémorise votre préférence de langue dans le navigateur pour vos prochaines visites.'],['Caméra et QR','La caméra est demandée lorsque vous activez le scanner, avec votre autorisation. Le code de cette maquette analyse les images sur votre appareil pour lire le QR ; il ne comporte pas de fonction d’envoi de ces images à l’atelier. Vous pouvez aussi saisir le numéro de série.'],['Contact et liens externes','Les boutons de contact ouvrent Instagram. La maquette ne comporte ni formulaire de contact ni système de paiement propre. Les politiques des plateformes externes s’appliquent lors de leur consultation.'],['Politique définitive à compléter','Préciser le responsable, le contact de confidentialité, les finalités, bases juridiques, destinataires, durées de conservation, droits et réclamation auprès de la CNIL. Vérifier également les journaux, cookies et services de l’hébergement final.']]},
en:{home:'Home',order:'Commission a guitar',terms:'Terms of sale',legal:'Legal notice',privacy:'Privacy',draft:'DRAFT · TO BE COMPLETED AND VALIDATED',notice:'This page is part of the prototype. Commercial terms and legal details have not yet been approved for final publication.',orderTitle:'Your guitar begins with a conversation.',orderLead:'Choosing an instrument brings your playing together with the work of the workshop.',steps:[['01 · Talk','Tell me about your music, your expectations and the model that interests you. We can discuss the possibility of trying the guitars.'],['02 · Define the instrument','We explore the model, your preferences for sound and comfort, woods and details that may be adapted to the project.'],['03 · Receive a proposal','Before confirmation, we set out the specifications, price, applicable taxes, estimated timing, payment and delivery arrangements in writing.'],['04 · Making and delivery','The instrument is made according to the agreed project. Collection or shipping and care guidance are arranged with the workshop.']],contact:'Discuss a commission',seeTerms:'Read the terms of sale',termsLead:'A working outline for the workshop’s own terms. This prototype does not allow purchases to be concluded or payments to be made.',clauses:[['Seller and scope','Complete the seller’s legal identity and define terms for available instruments, custom commissions and sales to consumers or professionals.'],['Quotation and confirmation','Define quotation validity, acceptance procedure and when an order is confirmed.'],['Price and payment','Complete currency, taxes, payment methods, the nature and amount of the initial payment, instalments and balance. No percentage or amount has been set in this prototype.'],['Timing and changes','Define how timing is communicated, how requested changes are handled and what happens in the event of a delay.'],['Delivery and transport','Specify collection or shipping, destinations, packaging, costs, responsibilities and the procedure for transport damage.'],['Cancellation, returns and withdrawal','Draft terms according to the type of sale and instrument, including applicable rights and, where relevant, the exception for goods made to the consumer’s specifications or clearly personalised. No blanket exclusion of returns is established here.'],['Guarantees and care','Distinguish applicable statutory guarantees from any additional commercial warranty. Complete scope, claims handling and care instructions without reducing statutory rights.'],['Complaints and mediation','Complete complaints contact details, the competent consumer mediator’s details and applicable dispute resolution procedures.']],legalLead:'Details of the website publisher and its final hosting provider.',fields:[['Workshop name','Victor Iermito · Luthier'],['Activity','Handcrafted classical guitars · France'],['Business operator and legal status','To be completed and verified'],['Business address','To be completed'],['Identification and registration (SIREN/SIRET and applicable register)','To be completed'],['VAT, where applicable','To be completed'],['Professional email and telephone','To be confirmed for publication'],['Publication director','To be confirmed'],['Final hosting: entity, address and telephone','To be completed once final hosting is selected']],rights:'Texts, photographs and logo',rightsText:'Before publication, confirm ownership and permission to use each photograph, text, recording and graphic element. External links lead to websites with their own terms.',privacyLead:'How this prototype works and what remains to be completed for the final website’s privacy policy.',privacySections:[['Language','The prototype stores your language preference in the browser for future visits.'],['Camera and QR','Camera access is requested when you activate the scanner and requires your permission. This prototype’s code analyses images on your device to read the QR; it includes no function for sending them to the workshop. You can also enter the serial number.'],['Contact and external links','Contact buttons open Instagram. This prototype has no contact form or payment system of its own. External platforms apply their own policies when you visit them.'],['Final policy pending','Complete controller, privacy contact, purposes, legal bases, recipients, retention, rights and complaints to the CNIL. Also review the final hosting provider’s logs, cookies and services.']]}
};
function practicalLinks(){const c=practical[lang];return [['order','/order'],['terms','/terms'],['legal','/legal'],['privacy','/privacy']].map(([k,url])=>`<a href="#${url}">${c[k]}</a>`).join('')}
function renderPracticalFooter(){let nav=document.querySelector('.practical-footer');if(!nav){nav=document.createElement('div');nav.className='practical-footer';document.querySelector('footer').append(nav)}nav.innerHTML=practicalLinks();}
function renderPractical(kind){const c=practical[lang];const title=kind==='order'?c.orderTitle:c[kind];const lead=kind==='order'?c.orderLead:c[kind+'Lead'];let body='';if(kind==='order'){body=`<div class="order-steps">${c.steps.map(([h,p])=>`<article><h2>${h}</h2><p>${p}</p></article>`).join('')}</div><a class="custom-button" href="https://www.instagram.com/victoriermitoluthier/" target="_blank" rel="noopener">${c.contact} ↗</a><p><a class="text-link" href="#/terms">${c.seeTerms} ↗</a></p>`}else if(kind==='legal'){body=`<dl class="legal-fields">${c.fields.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><h2>${c.rights}</h2><p>${c.rightsText}</p>`}else{body=(kind==='terms'?c.clauses:c.privacySections).map(([h,p])=>`<article><h2>${h}</h2><p>${p}</p></article>`).join('')}
main.innerHTML=`<section class="practical-page"><a class="breadcrumbs" href="#/">← ${c.home}</a><p class="eyebrow">VICTOR IERMITO</p><h1>${title}</h1><p class="practical-lead">${lead}</p><aside class="legal-draft"><strong>${c.draft}</strong><p>${c.notice}</p></aside><div class="practical-body">${body}</div><div class="practical-related">${practicalLinks()}</div></section>`;applyLanguage();}
const navBeforePractical=updateNav;updateNav=function(){navBeforePractical();const a=document.createElement('a');a.href='#/order';a.textContent=practical[lang].order;document.querySelector('header nav').append(a);renderPracticalFooter();};
route();
